function PatientsPage(){
  const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]); const[loading,setLoading]=useState(true); const[open,setOpen]=useState(false); const[detail,setDetail]=useState<any>(null); const[history,setHistory]=useState<any[]>([]); const[editing,setEditing]=useState<any>(null); const[name,setName]=useState(''); const[phone,setPhone]=useState(''); const[whatsapp,setWhatsapp]=useState(''); const[email,setEmail]=useState(''); const[cpf,setCpf]=useState(''); const[birthDate,setBirthDate]=useState(''); const[zip,setZip]=useState(''); const[street,setStreet]=useState(''); const[number,setNumber]=useState(''); const[complement,setComplement]=useState(''); const[neighborhood,setNeighborhood]=useState(''); const[city,setCity]=useState(''); const[state,setState]=useState(''); const[notes,setNotes]=useState(''); const[status,setStatus]=useState<'active'|'inactive'>('active'); const[search,setSearch]=useState(''); const[error,setError]=useState(''); const[busy,setBusy]=useState(false);
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);const{data,error}=await supabase.from('patients').select('*').eq('company_id',activeCompany.id).order('full_name');if(error)setError(error.message);setItems(data||[]);setLoading(false)} useEffect(()=>{load()},[activeCompany?.id]);
  function openNew(){setEditing(null);setName('');setPhone('');setWhatsapp('');setEmail('');setCpf('');setBirthDate('');setZip('');setStreet('');setNumber('');setComplement('');setNeighborhood('');setCity('');setState('');setNotes('');setStatus('active');setError('');setOpen(true)} function openEdit(p:any){setEditing(p);setName(p.full_name||'');setPhone(p.phone||'');setWhatsapp(p.whatsapp||'');setEmail(p.email||'');setCpf(p.cpf||'');setBirthDate(p.birth_date||'');setZip(p.zip_code||'');setStreet(p.street||'');setNumber(p.number||'');setComplement(p.complement||'');setNeighborhood(p.neighborhood||'');setCity(p.city||'');setState(p.state||'');setNotes(p.notes||'');setStatus(p.status==='inactive'?'inactive':'active');setError('');setOpen(true)}
  async function openDetail(p:any){setDetail(p);setHistory([]);setError('');if(!supabase||!activeCompany)return;const{data,error}=await supabase.from('appointments').select('*,professionals(name)').eq('company_id',activeCompany.id).eq('patient_id',p.id).order('starts_at',{ascending:false});if(error)setError(error.message);setHistory(data||[])}
  async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setBusy(true);setError('');const payload={full_name:name.trim(),phone:phone.trim()||null,whatsapp:whatsapp.trim()||null,email:email.trim()||null,cpf:cpf.trim()||null,birth_date:birthDate||null,zip_code:zip.trim()||null,street:street.trim()||null,number:number.trim()||null,complement:complement.trim()||null,neighborhood:neighborhood.trim()||null,city:city.trim()||null,state:state.trim().toUpperCase()||null,notes:notes.trim()||null,status};const result=editing?await supabase.from('patients').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase.from('patients').insert({company_id:activeCompany.id,...payload});if(result.error)setError(result.error.message);else{setOpen(false);await load()}setBusy(false)}
  const filtered=items.filter(p=>String(p.full_name||'').toLowerCase().includes(search.toLowerCase())||String(p.whatsapp||p.phone||'').includes(search));
  return <TenantPage title="Pacientes" description="Cadastro, contato e histórico dos pacientes." action={<button className="hero-btn" onClick={openNew}><Plus size={16}/> Novo paciente</button>}><section className="panel directory-panel patients-panel"><div className="head directory-head"><div><h2>Pacientes</h2><p>{items.length} cadastro(s)</p></div><div className="directory-search"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nome ou telefone..."/></div></div>{error&&<div className="form-error">{error}</div>}{loading?<div className="empty-box">Carregando...</div>:filtered.length===0?<div className="empty-box"><Users size={35}/><h2>{items.length?'Nenhum resultado':'Nenhum paciente'}</h2><p>{items.length?'Tente outro nome ou telefone.':'Cadastre o primeiro paciente deste consultório.'}</p></div>:filtered.map(p=><div className="row directory-row" key={p.id}><UserRound size={18}/><span><b>{p.full_name}</b><small>{p.whatsapp||p.phone||'Sem telefone'}</small></span><i className={p.status==='active'?'status-badge active':'status-badge inactive'}>{p.status==='active'?'Ativo':'Inativo'}</i><div className="row-actions"><button className="directory-action" onClick={()=>openDetail(p)}>Ver histórico</button><button className="directory-action" onClick={()=>openEdit(p)}>Editar</button></div></div>)}</section>{open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar paciente':'Novo paciente'}</h2><p>Dados básicos e status do cadastro.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome completo*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>CPF<input value={cpf} onChange={e=>setCpf(e.target.value)} placeholder="000.000.000-00"/></label><label>Data de nascimento<input type="date" value={birthDate} onChange={e=>setBirthDate(e.target.value)}/></label><label>Telefone<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>WhatsApp<input value={whatsapp} onChange={e=>setWhatsapp(e.target.value)}/></label><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><div className="form-section-label">Endereço</div><label>CEP<input value={zip} onChange={e=>setZip(e.target.value)}/></label><label>Rua<input value={street} onChange={e=>setStreet(e.target.value)}/></label><label>Número<input value={number} onChange={e=>setNumber(e.target.value)}/></label><label>Complemento<input value={complement} onChange={e=>setComplement(e.target.value)}/></label><label>Bairro<input value={neighborhood} onChange={e=>setNeighborhood(e.target.value)}/></label><label>Cidade<input value={city} onChange={e=>setCity(e.target.value)}/></label><label>Estado<input maxLength={2} value={state} onChange={e=>setState(e.target.value.toUpperCase())}/></label><label className="full-field">Observações<textarea rows={4} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Informações importantes sobre o paciente..."/></label>{editing&&<label>Status<select value={status} onChange={e=>setStatus(e.target.value as any)}><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label>}</div>{error&&<div className="form-error">{error}</div>}<button className="hero-btn" disabled={busy}>{busy?'Salvando...':editing?'Salvar alterações':'Salvar paciente'}</button></form></div>}{detail&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setDetail(null)}}><div className="modal panel patient-history-modal"><div className="modal-titlebar"><div className="professional-heading"><div className="professional-avatar"><UserRound size={22}/></div><div><h2>{detail.full_name}</h2><p>{detail.whatsapp||detail.phone||'Sem telefone cadastrado'}{detail.email?' · '+detail.email:''}</p></div></div><button type="button" className="icon-btn modal-close" aria-label="Fechar" onClick={()=>setDetail(null)}><XCircle size={19}/></button></div><div className="patient-history-summary"><div><b>{history.length}</b><span>atendimentos</span></div><div><b>{history.filter(a=>a.status==='completed'||a.status==='done').length}</b><span>realizados</span></div><div><b>{history.filter(a=>a.status==='confirmed').length}</b><span>confirmados</span></div></div><div className="modal-section-heading"><div><h3>Histórico de atendimentos</h3><p>Consultas registradas para este paciente, da mais recente à mais antiga.</p></div></div>{history.length===0?<div className="agenda-empty"><CalendarDays size={28}/><strong>Nenhum atendimento encontrado</strong><span>Este paciente ainda não possui atendimentos registrados.</span></div>:<div className="patient-history-list">{history.map(a=><div className="patient-history-item" key={a.id}><div className="appointment-date"><b>{new Date(a.starts_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','')}</b><span>{new Date(a.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span></div><div className="appointment-info"><strong>{a.professionals?.name||'Profissional'}</strong><span>{a.appointment_type||'Consulta'}{a.notes?' · '+a.notes:''}</span></div><span className={'appointment-status '+String(a.status||'').toLowerCase()}>{a.status==='confirmed'?'Confirmado':a.status==='completed'||a.status==='done'?'Realizado':a.status==='cancelled'?'Cancelado':a.status==='scheduled'?'Agendado':a.status==='no_show'?'Faltou':a.status||'Sem status'}</span></div>)}</div>}<div className="modal-footer"><button type="button" className="directory-action" onClick={()=>setDetail(null)}>Fechar</button></div></div></div>}</TenantPage>
}

function ProfessionalsPage(){
  const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]); const[loading,setLoading]=useState(true); const[open,setOpen]=useState(false); const[detail,setDetail]=useState<any>(null); const[history,setHistory]=useState<any[]>([]); const[editing,setEditing]=useState<any>(null); const[name,setName]=useState(''); const[specialty,setSpecialty]=useState(''); const[registration,setRegistration]=useState(''); const[status,setStatus]=useState<'active'|'inactive'>('active'); const[search,setSearch]=useState(''); const[error,setError]=useState(''); const[busy,setBusy]=useState(false);
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);const{data,error}=await supabase.from('professionals').select('*').eq('company_id',activeCompany.id).order('name');if(error)setError(error.message);setItems(data||[]);setLoading(false)} useEffect(()=>{load()},[activeCompany?.id]);
  function openNew(){setEditing(null);setName('');setSpecialty('');setRegistration('');setStatus('active');setError('');setOpen(true)} function openEdit(p:any){setEditing(p);setName(p.name||'');setSpecialty(p.specialty||'');setRegistration(p.professional_registration||'');setStatus(p.status==='inactive'?'inactive':'active');setError('');setOpen(true)}
  async function openDetail(p:any){setDetail(p);setHistory([]);if(!supabase||!activeCompany)return;const{data,error}=await supabase.from('appointments').select('*,patients(full_name)').eq('company_id',activeCompany.id).eq('professional_id',p.id).order('starts_at',{ascending:false});if(error)setError(error.message);setHistory(data||[])}
  async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setBusy(true);setError('');const payload={name:name.trim(),specialty:specialty.trim()||null,professional_registration:registration.trim()||null,status};const result=editing?await supabase.from('professionals').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase.from('professionals').insert({company_id:activeCompany.id,...payload});if(result.error)setError(result.error.message);else{setOpen(false);await load()}setBusy(false)}
  const filtered=items.filter(p=>String(p.name||'').toLowerCase().includes(search.toLowerCase())||String(p.specialty||'').toLowerCase().includes(search.toLowerCase())||String(p.professional_registration||'').toLowerCase().includes(search.toLowerCase()));
  return <TenantPage title="Profissionais" description="Equipe, especialidades e agenda de atendimento." action={<button className="hero-btn" onClick={openNew}><Plus size={16}/> Novo profissional</button>}><section className="panel directory-panel professionals-panel"><div className="head directory-head"><div><h2>Equipe</h2><p>{items.length} profissional(is)</p></div><div className="directory-search"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nome, especialidade..."/></div></div>{error&&<div className="form-error">{error}</div>}{loading?<div className="empty-box">Carregando...</div>:filtered.length===0?<div className="empty-box"><UserRound size={35}/><h2>{items.length?'Nenhum resultado':'Nenhum profissional'}</h2><p>{items.length?'Tente outro termo.':'Cadastre o primeiro profissional deste consultório.'}</p></div>:filtered.map(p=><div className="row directory-row" key={p.id}><UserRound size={18}/><span><b>{p.name}</b><small>{p.specialty||'Especialidade não informada'} {p.professional_registration?'· '+p.professional_registration:''}</small></span><i className={p.status==='active'?'status-badge active':'status-badge inactive'}>{p.status==='active'?'Ativo':'Inativo'}</i><div className="row-actions"><button className="directory-action" onClick={()=>openDetail(p)}>Ver agenda</button><button className="directory-action" onClick={()=>openEdit(p)}>Editar</button></div></div>)}</section>{open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar profissional':'Novo profissional'}</h2><p>Dados usados na Agenda e nos atendimentos.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Especialidade<input value={specialty} onChange={e=>setSpecialty(e.target.value)}/></label><label>Registro profissional<input value={registration} onChange={e=>setRegistration(e.target.value)}/></label><label>Status<select value={status} onChange={e=>setStatus(e.target.value as any)}><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label></div>{error&&<div className="form-error">{error}</div>}<button className="hero-btn" disabled={busy}>{busy?'Salvando...':editing?'Salvar alterações':'Salvar profissional'}</button></form></div>}{detail&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setDetail(null)}}><div className="modal panel professional-agenda-modal"><div className="modal-titlebar"><div className="professional-heading"><div className="professional-avatar"><UserRound size={22}/></div><div><h2>{detail.name}</h2><p>{detail.specialty||'Especialidade não informada'}{detail.professional_registration?' · '+detail.professional_registration:''}</p></div></div><button type="button" className="icon-btn modal-close" aria-label="Fechar" onClick={()=>setDetail(null)}><XCircle size={19}/></button></div><div className="agenda-summary"><div><b>{history.length}</b><span>{history.length===1?'atendimento':'atendimentos'}</span></div><div><b>{history.filter(a=>a.status==='confirmed').length}</b><span>confirmados</span></div><div><b>{history.filter(a=>a.status==='completed'||a.status==='done').length}</b><span>realizados</span></div></div><div className="modal-section-heading"><div><h3>Agenda do profissional</h3><p>Atendimentos registrados para este profissional.</p></div></div>{history.length===0?<div className="agenda-empty"><CalendarDays size={28}/><strong>Nenhum atendimento encontrado</strong><span>Este profissional ainda não possui atendimentos registrados.</span></div>:<div className="professional-appointments">{history.map(a=><div className="professional-appointment" key={a.id}><div className="appointment-date"><b>{new Date(a.starts_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','')}</b><span>{new Date(a.starts_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span></div><div className="appointment-info"><strong>{a.patients?.full_name||'Paciente'}</strong><span>{a.appointment_type||'Consulta'}</span></div><span className={'appointment-status '+String(a.status||'').toLowerCase()}>{a.status==='confirmed'?'Confirmado':a.status==='completed'||a.status==='done'?'Realizado':a.status==='cancelled'?'Cancelado':a.status==='scheduled'?'Agendado':a.status||'Sem status'}</span></div>)}</div>}<div className="modal-footer"><button type="button" className="directory-action" onClick={()=>setDetail(null)}>Fechar</button></div></div></div>}</TenantPage>
}

function TemplatesPage(){
  const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]); const[loading,setLoading]=useState(true); const[open,setOpen]=useState(false); const[editing,setEditing]=useState<any>(null); const[error,setError]=useState(''); const[success,setSuccess]=useState(''); const[busy,setBusy]=useState(false); const[name,setName]=useState(''); const[description,setDescription]=useState(''); const[category,setCategory]=useState('Geral'); const[blocks,setBlocks]=useState<any[]>([]); const[selected,setSelected]=useState(0); const[filter,setFilter]=useState(''); const[testPhone,setTestPhone]=useState('');
  const variables=[['nome','Nome do paciente'],['telefone','Telefone'],['data','Data da consulta'],['hora','Horário'],['profissional','Profissional'],['especialidade','Especialidade'],['empresa','Nome do consultório'],['link_confirmacao','Link de confirmação'],['link_cancelamento','Link de cancelamento'],['link_reagendamento','Link de reagendamento']];
  const samples:any={nome:'Alexandre',telefone:'+55 11 99999-9999',data:'03/09/2026',hora:'14:30',profissional:'Dra. Mariana',especialidade:'Clínica Geral',empresa:activeCompany?.name||'Clínica Consulta Pro',link_confirmacao:'https://consulta.pro/confirmar',link_cancelamento:'https://consulta.pro/cancelar',link_reagendamento:'https://consulta.pro/remarcar'};
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);setError('');const{data,error}=await supabase.from('message_templates').select('*').eq('company_id',activeCompany.id).order('created_at',{ascending:false});if(error)setError(error.message);setItems(data||[]);setLoading(false)} useEffect(()=>{load()},[activeCompany?.id]);
  function reset(){setEditing(null);setName('');setDescription('');setCategory('Geral');setBlocks([{id:crypto.randomUUID(),type:'text',text:'Olá, {{nome}}! 👋\n\nSua consulta está confirmada para {{data}} às {{hora}} com {{profissional}}.'}]);setSelected(0);setError('');setSuccess('');setTestPhone('');setOpen(true)}
  function edit(t:any){setEditing(t);setName(t.name||'');setDescription(t.description||'');setCategory(t.category||'Geral');let b=t.components||t.content?.blocks;if(typeof b==='string'){try{b=JSON.parse(b)}catch{b=null}}if(!Array.isArray(b)){b=t.body?[{id:crypto.randomUUID(),type:'text',text:t.body}]:[{id:crypto.randomUUID(),type:'text',text:''}]}setBlocks(b);setSelected(0);setError('');setSuccess('');setOpen(true)}
  function add(type:string){const b=type==='text'?{id:crypto.randomUUID(),type,text:''}:type==='button'?{id:crypto.randomUUID(),type,text:'Confirmar consulta',url:''}:{id:crypto.randomUUID(),type,text:''};setBlocks(v=>[...v,b]);setSelected(blocks.length)}
  function move(i:number,j:number){if(j<0||j>=blocks.length)return;setBlocks(v=>{const x=[...v];[x[i],x[j]]=[x[j],x[i]];return x});setSelected(j)}
  function remove(i:number){setBlocks(v=>v.filter((_,n)=>n!==i));setSelected(Math.max(0,Math.min(selected,blocks.length-2)))}
  function replaceVariables(text:string){return text.replace(/\{\{\s*([a-zA-Z_]+)\s*\}\}/g,(_,k)=>samples[k]??`{{${k}}}`)}
  const preview=blocks.map(b=>b.type==='button'?`[ ${replaceVariables(b.text||'Botão')} ]`:b.type==='image'?'🖼️ Imagem':replaceVariables(b.text||'')).join('\n\n');
  async function save(){if(!supabase||!activeCompany)return;if(!name.trim()){setError('Informe um nome.');return}if(!blocks.length||!blocks.some(b=>String(b.text||'').trim())){setError('Adicione pelo menos um bloco de conteúdo.');return}setBusy(true);setError('');const body=blocks.map(b=>b.type==='button'?b.text:`${b.text||''}`).join('\n');const payload={name:name.trim(),description:description.trim()||null,category,body,active:true,components:blocks,variables:Array.from(new Set((JSON.stringify(blocks).match(/\{\{([a-zA-Z_]+)\}\}/g)||[]).map((x:string)=>x.slice(2,-2).trim())))};const result=editing?await supabase.from('message_templates').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase.from('message_templates').insert({company_id:activeCompany.id,...payload});if(result.error)setError(result.error.message);else{setOpen(false);await load()}setBusy(false)}
  async function toggle(t:any){if(!supabase||!activeCompany)return;const{error}=await supabase.from('message_templates').update({active:!t.active}).eq('id',t.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else await load()}
  async function duplicate(t:any){if(!supabase||!activeCompany)return;const copy={...t};delete copy.id;delete copy.created_at;delete copy.updated_at;copy.name=`${t.name} (cópia)`;copy.company_id=activeCompany.id;const{error}=await supabase.from('message_templates').insert(copy);if(error)setError(error.message);else await load()}
  async function removeTemplate(t:any){if(!supabase||!activeCompany)return;if(!confirm(`Excluir o template “${t.name}”?`))return;const{error}=await supabase.from('message_templates').delete().eq('id',t.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else await load()}
  async function sendTest(){if(!supabase||!activeCompany)return;if(!editing?.id){setError('Salve o template antes de enviar um teste.');return}if(!testPhone.trim()){setError('Informe o número de teste.');return}setBusy(true);setError('');const{data,error}=await supabase.functions.invoke('enviar-mensagem',{body:{company_id:activeCompany.id,template_id:editing.id,recipient_number:testPhone.trim()}});if(error)setError(error.message);else if(data?.error)setError(data.error);else setSuccess('Mensagem de teste enviada.');setBusy(false)}
  const filtered=items.filter(t=>!filter||String(t.name||'').toLowerCase().includes(filter.toLowerCase())||String(t.category||'').toLowerCase().includes(filter.toLowerCase()));
  return <TenantPage title="Templates" description="Crie mensagens reutilizáveis para WhatsApp, com variáveis e preview." action={<button className="hero-btn" onClick={reset}><Plus size={16}/> Novo template</button>}><section className="panel"><div className="head"><div><h2>Modelos de mensagem</h2><p>{items.length} template(s)</p></div><input style={{maxWidth:280}} value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Buscar template..."/></div>{error&&<div className="form-error">{error}</div>}{loading?<div className="empty-box">Carregando...</div>:filtered.length===0?<div className="empty-box"><MessageCircle size={32}/><h2>Nenhum template</h2><p>Crie seu primeiro modelo para usar em automações.</p><button className="hero-btn" onClick={reset}><Plus size={16}/> Criar template</button></div>:filtered.map(t=><div className="row" key={t.id}><MessageCircle size={18}/><span><b>{t.name}</b><small>{t.category||'Geral'} · {t.variables?.length||0} variável(is)</small></span><i>{t.active?'Ativo':'Inativo'}</i><button className="back-link" onClick={()=>edit(t)}>Editar</button><button className="back-link" onClick={()=>duplicate(t)}><Copy size={14}/> Duplicar</button><button className="back-link" onClick={()=>toggle(t)}>{t.active?'Desativar':'Ativar'}</button><button className="back-link" onClick={()=>removeTemplate(t)}><Trash2 size={14}/></button></div>)}</section>
    {open&&<div className="modal-backdrop"><div className="modal panel" style={{maxWidth:1200,width:'95vw'}}><div className="head"><div><h2>{editing?'Editar template':'Novo template'}</h2><p>Editor visual com blocos, variáveis e preview.</p></div><button className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome*<input value={name} onChange={e=>setName(e.target.value)} placeholder="Lembrete de consulta"/></label><label>Categoria<select value={category} onChange={e=>setCategory(e.target.value)}>{['Confirmação de consulta','Lembrete','Cancelamento','Reagendamento','Pós-consulta','Aniversário','Cobrança','Geral'].map(x=><option key={x}>{x}</option>)}</select></label><label>Descrição<input value={description} onChange={e=>setDescription(e.target.value)} placeholder="Quando e por que usar este template"/></label></div><div className="grid" style={{gridTemplateColumns:'190px minmax(0,1fr) 300px',gap:16,marginTop:16}}><div className="panel" style={{padding:12}}><h3>Componentes</h3><button className="back-link" onClick={()=>add('text')}>+ Texto</button><button className="back-link" onClick={()=>add('button')}>+ Botão</button><button className="back-link" onClick={()=>add('image')}>+ Imagem</button><h3 style={{marginTop:16}}>Variáveis</h3>{variables.map(([k,l])=><button key={k} className="back-link" onClick={()=>setBlocks(v=>{const x=[...v];const i=Math.min(selected,x.length-1);if(i<0)return v;x[i]={...x[i],text:`${x[i].text||''} {{${k}}}`};return x})}>{`{{${k}}}`}<small style={{display:'block'}}>{l}</small></button>)}</div><div className="panel" style={{padding:16,minHeight:420}}><h3>Canvas</h3>{blocks.length===0&&<div className="empty-box">Adicione um bloco para começar.</div>}{blocks.map((b,i)=><div key={b.id} onClick={()=>setSelected(i)} style={{border:selected===i?'2px solid currentColor':'1px solid #ddd',borderRadius:10,padding:12,marginBottom:10,cursor:'pointer'}}><div style={{display:'flex',justifyContent:'space-between',gap:8,alignItems:'center'}}><b>{b.type==='text'?'Texto':b.type==='button'?'Botão':'Imagem'}</b><span><button type="button" className="icon-btn" onClick={e=>{e.stopPropagation();move(i,i-1)}}>↑</button><button type="button" className="icon-btn" onClick={e=>{e.stopPropagation();move(i,i+1)}}>↓</button><button type="button" className="icon-btn" onClick={e=>{e.stopPropagation();remove(i)}}><Trash2 size={15}/></button></span></div>{b.type==='image'?<input value={b.text||''} onChange={e=>setBlocks(v=>v.map((x,n)=>n===i?{...x,text:e.target.value}:x))} placeholder="URL da imagem"/>:b.type==='button'?<div className="form-grid"><label>Texto<input value={b.text||''} onChange={e=>setBlocks(v=>v.map((x,n)=>n===i?{...x,text:e.target.value}:x))}/></label><label>URL<input value={b.url||''} onChange={e=>setBlocks(v=>v.map((x,n)=>n===i?{...x,url:e.target.value}:x))}/></label></div>:<textarea rows={5} value={b.text||''} onChange={e=>setBlocks(v=>v.map((x,n)=>n===i?{...x,text:e.target.value}:x))} placeholder="Digite a mensagem..."/>}</div>)}</div><div><div className="panel" style={{padding:16,position:'sticky',top:12}}><h3>Preview WhatsApp</h3><div style={{background:'#efeae2',padding:16,borderRadius:12,minHeight:250}}><div style={{background:'#fff',padding:12,borderRadius:'12px 12px 2px 12px',whiteSpace:'pre-wrap',boxShadow:'0 1px 2px rgba(0,0,0,.08)'}}>{preview||'Sua mensagem aparecerá aqui.'}</div></div><h3 style={{marginTop:16}}>Enviar teste</h3><input value={testPhone} onChange={e=>setTestPhone(e.target.value)} placeholder="5511999999999"/><button type="button" className="hero-btn" style={{marginTop:8}} disabled={busy} onClick={sendTest}>Enviar teste</button></div></div></div><div className="head" style={{marginTop:16}}><button className="back-link" onClick={()=>setOpen(false)}>Cancelar</button><button className="hero-btn" disabled={busy} onClick={save}>{busy?'Salvando...':'Salvar template'} <CheckCircle2 size={16}/></button></div>{error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}</div></div>}
  </TenantPage>
}

function WhatsAppPage(){ const{activeCompany}=useTenant(); const[item,setItem]=useState<any>(null); const[templates,setTemplates]=useState<any[]>([]); const[messages,setMessages]=useState<any[]>([]); const[loading,setLoading]=useState(true); const[busy,setBusy]=useState(false); const[error,setError]=useState(''); const[success,setSuccess]=useState(''); const[qr,setQr]=useState<string|null>(null); const[filter,setFilter]=useState(''); async function load(){if(!supabase||!activeCompany)return;setLoading(true);setError('');const[w,t,m]=await Promise.all([supabase.from('whatsapp_integrations').select('*').eq('company_id',activeCompany.id).maybeSingle(),supabase.from('message_templates').select('*').eq('company_id',activeCompany.id).order('created_at',{ascending:false}),supabase.from('whatsapp_messages').select('id,recipient_number,direction,kind,body,status,sent_at,created_at').eq('company_id',activeCompany.id).order('created_at',{ascending:false}).limit(50)]);if(w.error||t.error||m.error)setError(w.error?.message||t.error?.message||m.error?.message||'Não foi possível carregar o WhatsApp.');setItem(w.data||null);setTemplates(t.data||[]);setMessages(m.data||[]);setLoading(false)} useEffect(()=>{load()},[activeCompany?.id]); async function session(action:string){if(!supabase||!activeCompany)return;setBusy(true);setError('');setSuccess('');const{data,error}=await supabase.functions.invoke('manage-evolution-session',{body:{action,company_id:activeCompany.id}});if(error){setError(error.message||'Não foi possível comunicar com o WhatsApp.');setBusy(false);return}if(data?.error){setError(data.error);setBusy(false);return}if(data?.qr){const q=data.qr?.value||data.qr?.qr||data.qr?.data||data.qr;if(typeof q==='string')setQr(q.startsWith('data:')?q:`data:image/png;base64,${q}`)}if(data?.status==='connected')setQr(null);setSuccess(data?.status==='connected'?'WhatsApp conectado.':'Sessão atualizada.');setBusy(false);await load()} useEffect(()=>{if(!item||item.status!=='connecting')return;const timer=setInterval(()=>session('status'),5000);return()=>clearInterval(timer)},[item?.status]); const statusLabel=item?.status==='connected'?'Conectado':item?.status==='connecting'?'Conectando':item?.status==='error'?'Erro':'Desconectado'; const filtered=messages.filter(m=>!filter||String(m.recipient_number||'').includes(filter)||String(m.body||'').toLowerCase().includes(filter.toLowerCase())); return <TenantPage title="WhatsApp" description="Conecte o WhatsApp do consultório e gerencie mensagens padrão."><section className="panel whatsapp-panel"><div className="head"><div><h2>WhatsApp</h2><p>Conecte o número do consultório para enviar mensagens aos pacientes.</p></div><i>{statusLabel}</i></div>{loading?<div className="empty-box">Carregando...</div>:<>{item?.status==='connected'&&<div className="wa-status-card"><div className="wa-status-icon"><Wifi size={22}/></div><span><b>{item.phone_number||'WhatsApp conectado'}</b><small>Conectado e pronto para enviar mensagens.</small></span></div>}{item?.status==='connecting'&&<div className="wa-qr-box"><Wifi size={30}/><h2>Conecte seu WhatsApp</h2><p>Abra o WhatsApp no celular, vá em <b>Dispositivos conectados</b> e escaneie o QR Code.</p>{qr&&<img src={qr} alt="QR Code para conectar o WhatsApp"/>}</div>}{item?.status!=='connected'&&item?.status!=='connecting'&&<div className="empty-box"><MessageCircle size={30}/><h2>WhatsApp desconectado</h2><p>Conecte uma sessão para habilitar os disparos automáticos.</p></div>}{item?.status==='error'&&<div className="form-error">{item.last_error||'Falha na conexão.'}</div>}<div className="wa-actions"><button className="hero-btn" disabled={busy} onClick={()=>session(item?.status==='connecting'?'qr':'start')}>{busy?'Processando...':item?.status==='connected'?'Atualizar status':item?.status==='connecting'?'Atualizar QR':'Conectar WhatsApp'} <Wifi size={16}/></button>{item?.status==='connected'&&<button className="wa-action-secondary" disabled={busy} onClick={()=>session('start')}>Reconectar</button>}</div></>}</section><section className="panel"><div className="head"><div><h2>Mensagens enviadas</h2><p>Histórico recente de mensagens.</p></div><input style={{maxWidth:260}} value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filtrar número ou texto..."/></div>{filtered.length===0?<div className="empty-box"><MessageCircle size={30}/><p>Nenhuma mensagem encontrada.</p></div>:filtered.map(m=><div className="row" key={m.id}><MessageCircle size={17}/><span><b>{m.direction==='outbound'?'Enviada':'Recebida'} · {m.recipient_number||'Número não informado'}</b><small>{m.body||'Sem conteúdo'} · {formatZoned(m.created_at,activeCompany?.timezone||BR_TIMEZONE)}</small></span><i>{m.status||'registrada'}</i></div>)}</section>{error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}</TenantPage> }
function AutomationsPage(){ const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]);const[templates,setTemplates]=useState<any[]>([]);const[dispatches,setDispatches]=useState<any[]>([]); const[open,setOpen]=useState(false);const[editing,setEditing]=useState<any>(null);const[deleting,setDeleting]=useState<any>(null); const[name,setName]=useState('');const[type,setType]=useState('appointment_reminder');const[advance,setAdvance]=useState('1440');const[channel,setChannel]=useState('whatsapp');const[templateId,setTemplateId]=useState('');const[enabled,setEnabled]=useState(true); const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState('');const[success,setSuccess]=useState(''); async function load(){if(!supabase||!activeCompany)return;setLoading(true);setError('');const[a,t,d]=await Promise.all([supabase.from('automations').select('*').eq('company_id',activeCompany.id).order('name'),supabase.from('message_templates').select('id,name,active').eq('company_id',activeCompany.id).order('name'),supabase.from('automation_dispatches').select('id,automation_id,appointment_id,recipient_number,status,scheduled_for,sent_at,error_message,created_at').eq('company_id',activeCompany.id).order('created_at',{ascending:false}).limit(50)]);if(a.error||t.error||d.error)setError(a.error?.message||t.error?.message||d.error?.message||'Não foi possível carregar as automações.');setItems(a.data||[]);setTemplates((t.data||[]).filter(x=>x.active));setDispatches(d.data||[]);setLoading(false)} useEffect(()=>{load()},[activeCompany?.id]); function resetForm(){setEditing(null);setName('');setType('appointment_reminder');setAdvance('1440');setChannel('whatsapp');setTemplateId(templates[0]?.id||'');setEnabled(true);setError('');setSuccess('');setOpen(true)} function edit(a:any){setEditing(a);setName(a.name||'');setType(a.type||'appointment_reminder');setAdvance(String(a.advance_minutes??1440));setChannel(a.channel||'whatsapp');const m=templates.find(t=>t.name===a.message_template);setTemplateId(m?.id||'');setEnabled(Boolean(a.enabled));setError('');setSuccess('');setOpen(true)} async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;const selected=templates.find(t=>t.id===templateId);if(!name.trim()){setError('Informe um nome para a automação.');return}if(channel==='whatsapp'&&!selected){setError('Selecione um template ativo para o WhatsApp.');return}setSaving(true);setError('');const payload={company_id:activeCompany.id,name:name.trim(),type,advance_minutes:Math.max(0,Number(advance)||0),channel,message_template:selected?.name||'',enabled};const result=editing?await supabase.from('automations').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase.from('automations').insert(payload);if(result.error)setError(result.error.message);else{setSuccess(editing?'Automação atualizada.':'Automação criada.');setOpen(false);await load()}setSaving(false)} async function remove(){if(!supabase||!activeCompany||!deleting)return;const{error}=await supabase.from('automations').delete().eq('id',deleting.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else{setDeleting(null);setSuccess('Automação excluída.');await load()}} async function toggle(a:any){if(!supabase||!activeCompany)return;const{error}=await supabase.from('automations').update({enabled:!a.enabled}).eq('id',a.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else await load()} const pending=dispatches.filter(d=>d.status==='pending'||d.status==='scheduled').length;const sent=dispatches.filter(d=>d.status==='sent'||d.status==='completed').length;const failed=dispatches.filter(d=>d.status==='failed'||d.status==='error').length; return <TenantPage title="Automações" description="Regras de lembretes e mensagens automáticas." action={<button className="hero-btn" onClick={resetForm}><Plus size={16}/> Nova automação</button>}><div className="metrics"><Metric label="Ativas" value={items.filter(a=>a.enabled).length} icon={Bot}/><Metric label="Pendentes" value={pending} icon={Activity}/><Metric label="Enviadas" value={sent} icon={CheckCircle2}/><Metric label="Falhas" value={failed} icon={CircleAlert}/></div><section className="panel">{error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}{loading?<div className="empty-box">Carregando automações...</div>:items.length===0?<div className="empty-box"><Bot size={35}/><h2>Nenhuma automação</h2><p>Crie uma regra para lembretes de consulta.</p><button className="hero-btn" onClick={resetForm}><Plus size={16}/> Criar automação</button></div>:items.map(a=><div className="row" key={a.id}><Bot size={18}/><span><b>{a.name}</b><small>{a.advance_minutes>=1440?Math.round(a.advance_minutes/1440)+' dia(s)':a.advance_minutes>=60?Math.round(a.advance_minutes/60)+' hora(s)':a.advance_minutes+' min'} antes · {a.channel} · {a.message_template||'Sem template'}</small></span><i>{a.enabled?'Ativa':'Inativa'}</i><button className="back-link" onClick={()=>edit(a)}>Editar</button><button className="back-link" onClick={()=>toggle(a)}>{a.enabled?'Desativar':'Ativar'}</button><button className="back-link" onClick={()=>setDeleting(a)}>Excluir</button></div>)}</section><section className="panel"><div className="head"><div><h2>Histórico de disparos</h2><p>Últimos eventos registrados pelas automações.</p></div></div>{dispatches.length===0?<div className="empty-box"><Activity size={30}/><p>Nenhum disparo registrado ainda.</p></div>:dispatches.map(d=><div className="row" key={d.id}><Activity size={17}/><span><b>{d.recipient_number||'Número não informado'}</b><small>Agendado: {d.scheduled_for?formatZoned(d.scheduled_for,activeCompany?.timezone||BR_TIMEZONE):'—'}{d.sent_at?' · Enviado: '+formatZoned(d.sent_at,activeCompany?.timezone||BR_TIMEZONE):''}{d.error_message?' · '+d.error_message:''}</small></span><i>{d.status}</i></div>)}</section>{deleting&&<div className="modal-backdrop"><div className="modal panel"><h2>Excluir automação?</h2><p>O registro da regra será removido.</p><button className="hero-btn" onClick={remove}>Excluir</button> <button className="back-link" onClick={()=>setDeleting(null)}>Cancelar</button></div></div>}{open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar automação':'Nova automação'}</h2><p>Defina quando e qual mensagem será usada.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome*<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Lembrete de consulta"/></label><label>Gatilho<select value={type} onChange={e=>setType(e.target.value)}><option value="appointment_reminder">Lembrete de consulta</option><option value="appointment_confirmation">Confirmação de consulta</option><option value="appointment_followup">Pós-consulta</option></select></label><label>Antecedência<select value={advance} onChange={e=>setAdvance(e.target.value)}><option value="60">1 hora antes</option><option value="120">2 horas antes</option><option value="1440">1 dia antes</option><option value="2880">2 dias antes</option><option value="10080">7 dias antes</option></select></label><label>Canal<select value={channel} onChange={e=>setChannel(e.target.value)}><option value="whatsapp">WhatsApp</option><option value="manual">Manual</option></select></label><label>Mensagem padrão<select value={templateId} onChange={e=>setTemplateId(e.target.value)} disabled={channel!=='whatsapp'}><option value="">Selecione um template</option>{templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Status<select value={enabled?'active':'inactive'} onChange={e=>setEnabled(e.target.value==='active')}><option value="active">Ativa</option><option value="inactive">Inativa</option></select></label></div>{channel==='whatsapp'&&templates.length===0&&<div className="form-error">Nenhum template ativo. Crie uma mensagem padrão em WhatsApp antes de ativar esta automação.</div>}<div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':editing?'Salvar alterações':'Criar automação'} <CheckCircle2 size={16}/></button> <button type="button" className="back-link" onClick={()=>setOpen(false)}>Cancelar</button></div></form></div>}</TenantPage> }
function TenantSettingsPage(){ const{activeCompany}=useTenant(); const[name,setName]=useState('');const[legal,setLegal]=useState('');const[cnpj,setCnpj]=useState('');const[phone,setPhone]=useState('');const[email,setEmail]=useState('');const[timezone,setTimezone]=useState('America/Sao_Paulo');const[zip,setZip]=useState('');const[street,setStreet]=useState('');const[number,setNumber]=useState('');const[complement,setComplement]=useState('');const[neighborhood,setNeighborhood]=useState('');const[city,setCity]=useState('');const[state,setState]=useState('');const[fullName,setFullName]=useState('');const[loginEmail,setLoginEmail]=useState('');const[newPassword,setNewPassword]=useState('');const[showPassword,setShowPassword]=useState(false);const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState('');const[success,setSuccess]=useState('');useEffect(()=>{async function load(){if(!supabase||!activeCompany)return;setLoading(true);const[{data:c},{data:{user}}]=await Promise.all([supabase.from('companies').select('*').eq('id',activeCompany.id).maybeSingle(),supabase.auth.getUser()]);setName(c?.name||'');setTimezone(c?.timezone||'America/Sao_Paulo');setLegal(c?.legal_name||'');setCnpj(c?.cnpj||'');setPhone(c?.phone||'');setEmail(c?.email||'');setZip(c?.zip_code||'');setStreet(c?.street||'');setNumber(c?.number||'');setComplement(c?.complement||'');setNeighborhood(c?.neighborhood||'');setCity(c?.city||'');setState(c?.state||'');setLoginEmail(user?.email||'');if(user){const{data:p}=await supabase.from('profiles').select('full_name').eq('id',user.id).maybeSingle();setFullName(p?.full_name||'')}setLoading(false)}load()},[activeCompany?.id]); async function saveCompany(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setSaving(true);setError('');setSuccess('');const{error}=await supabase.from('companies').update({name:name.trim(),legal_name:legal||null,cnpj:cnpj||null,phone:phone||null,email:email||null,zip_code:zip||null,street:street||null,number:number||null,complement:complement||null,neighborhood:neighborhood||null,city:city||null,state:state||null}).eq('id',activeCompany.id);if(error)setError(error.message);else setSuccess('Dados do consultório salvos.');setSaving(false)} async function saveProfile(e:React.FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);setError('');setSuccess('');const{data:{user}}=await supabase.auth.getUser();if(!user){setError('Sessão expirada.');setSaving(false);return}const p=await supabase.from('profiles').upsert({id:user.id,full_name:fullName.trim()},{onConflict:'id'});if(p.error){setError(p.error.message);setSaving(false);return}if(newPassword){const u=await supabase.auth.updateUser({password:newPassword});if(u.error){setError(u.error.message);setSaving(false);return}}setNewPassword('');setSuccess('Perfil e segurança atualizados.');setSaving(false)}if(loading)return <TenantPage title="Configurações" description="Dados do consultório e da conta."><div className="panel">Carregando...</div></TenantPage>;return <TenantPage title="Configurações" description="Dados do consultório e da conta."><section className="panel"><div className="head"><div><h2>Consultório</h2><p>Dados exibidos e usados na operação.</p></div></div><form className="form-grid" onSubmit={saveCompany}><label>Nome fantasia*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Razão social<input value={legal} onChange={e=>setLegal(e.target.value)}/></label><label>CNPJ<input value={cnpj} onChange={e=>setCnpj(e.target.value)}/></label><label>Telefone<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>CEP<input value={zip} onChange={e=>setZip(e.target.value)}/></label><label>Rua<input value={street} onChange={e=>setStreet(e.target.value)}/></label><label>Número<input value={number} onChange={e=>setNumber(e.target.value)}/></label><label>Complemento<input value={complement} onChange={e=>setComplement(e.target.value)}/></label><label>Bairro<input value={neighborhood} onChange={e=>setNeighborhood(e.target.value)}/></label><label>Cidade<input value={city} onChange={e=>setCity(e.target.value)}/></label><label>Estado<input maxLength={2} value={state} onChange={e=>setState(e.target.value.toUpperCase())}/></label><div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':'Salvar dados'} <CheckCircle2 size={16}/></button></div></form></section><section className="panel"><div className="head"><div><h2>Minha conta</h2><p>Atualize seu nome e senha de acesso.</p></div></div><form className="form-grid" onSubmit={saveProfile}><label>Nome completo<input value={fullName} onChange={e=>setFullName(e.target.value)}/></label><label>E-mail de login<input disabled value={loginEmail}/></label><label>Nova senha<div className="password-wrap"><input type={showPassword?'text':'password'} minLength={8} value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="Deixe vazio para manter"/><button type="button" className="icon-btn" onClick={()=>setShowPassword(v=>!v)}>{showPassword?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label><div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':'Salvar conta'} <CheckCircle2 size={16}/></button></div></form></section>{error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}</TenantPage> }
function TenantDashboard(){const{activeCompany}=useTenant();const navigate=useNavigate();const[stats,setStats]=useState({today:0,confirmed:0,pending:0,done:0,patients:0,professionals:0});const[next,setNext]=useState<any[]>([]);const[wa,setWa]=useState<any>(null);useEffect(()=>{async function load(){if(!supabase||!activeCompany)return;const{data:serverNow,error:clockError}=await supabase.rpc('server_now');if(clockError||!serverNow)return;const tz=activeCompany.timezone||BR_TIMEZONE;const dayKey=localDateKey(new Date(serverNow),tz);const start=localDateTimeToUtc(dayKey+'T00:00',tz);const end=localDateTimeToUtc(dayKey+'T23:59',tz);end.setTime(end.getTime()+60000);const[ap,pa,pr,wi]=await Promise.all([supabase.from('appointments').select('id,starts_at,status,patients(full_name),professionals(name)').eq('company_id',activeCompany.id).gte('starts_at',start.toISOString()).lt('starts_at',end.toISOString()).order('starts_at'),supabase.from('patients').select('*',{count:'exact',head:true}).eq('company_id',activeCompany.id),supabase.from('professionals').select('*',{count:'exact',head:true}).eq('company_id',activeCompany.id),supabase.from('whatsapp_integrations').select('status,phone_number').eq('company_id',activeCompany.id).maybeSingle()]);const list=ap.data||[];setNext(list.slice(0,5));setStats({today:list.length,confirmed:list.filter(x=>x.status==='confirmed').length,pending:list.filter(x=>x.status==='scheduled'||x.status==='pending').length,done:list.filter(x=>x.status==='completed'||x.status==='done').length,patients:pa.count||0,professionals:pr.count||0});setWa(wi.data||null)}load()},[activeCompany?.id]);return <div className="content"><div className="head"><div><h1>Dashboard</h1><p>{activeCompany?.name}</p></div><button className="hero-btn" onClick={()=>navigate('/agenda')}><Plus size={16}/> Novo atendimento</button></div><div className="metrics"><Metric label="Consultas hoje" value={stats.today} icon={CalendarDays}/><Metric label="Confirmadas" value={stats.confirmed} icon={CheckCircle2}/><Metric label="Pendentes" value={stats.pending} icon={Activity}/><Metric label="Realizadas" value={stats.done} icon={CheckCircle2}/></div><div className="grid"><section className="panel"><div className="head"><div><h2>Próximos atendimentos</h2><p>Agenda de hoje</p></div><button className="back-link" onClick={()=>navigate('/agenda')}>Ver agenda</button></div>{next.length===0?<Empty text="Nenhum atendimento para hoje."/>:next.map(a=><div className="row" key={a.id}><CalendarDays size={17}/><span><b>{new Intl.DateTimeFormat('pt-BR',{timeZone:activeCompany?.timezone||BR_TIMEZONE,hour:'2-digit',minute:'2-digit'}).format(new Date(a.starts_at))} · {a.patients?.full_name||'Paciente'}</b><small>{a.professionals?.name||'Profissional'} · {a.status}</small></span></div>)}</section><section className="panel"><h2>Resumo do consultório</h2><div className="stats"><div><b>{stats.patients}</b><small>pacientes</small></div><div><b>{stats.professionals}</b><small>profissionais</small></div></div><div className="wa" style={{marginTop:12}}><MessageCircle size={20}/><span><b>{wa?.status||'WhatsApp não conectado'}</b><small>{wa?.phone_number||'Configure o número da empresa.'}</small></span></div></section></div></div>}
export { PatientsPage, ProfessionalsPage, AgendaPage, WhatsAppPage, TemplatesPage, AutomationsPage, TenantSettingsPage, TenantDashboard }
